import java.util.Scanner;

public class Main {
    static final int MAXN = 510;
    static int total_m, total_n, modulus;
    static int[] factorial = new int[MAXN], inv_factorial = new int[MAXN], inv = new int[MAXN];
    static int[] f_arr = new int[MAXN], g_arr = new int[MAXN], prefix_sum = new int[MAXN];
    static int[][] f_table = new int[MAXN][MAXN], g_table = new int[MAXN][MAXN];

    static int sum_mod(int a, int b) {
        return (a + b) % modulus;
    }

    static int diff_mod(int a, int b) {
        return a - b < 0 ? a - b + modulus : a - b;
    }

    static int prod_mod(int a, int b) {
        return (int)((long)a * b % modulus);
    }

    static void precompute(int limit) {
        factorial[0] = 1;
        inv[1] = 1;
        factorial[1] = 1;
        inv_factorial[0] = 1;
        inv_factorial[1] = 1;
        for (int i = 2; i <= limit; i++) {
            inv[i] = prod_mod((modulus - modulus / i), inv[modulus % i]);
        }
        for (int i = 2; i <= limit; i++) {
            factorial[i] = prod_mod(factorial[i - 1], i);
            inv_factorial[i] = prod_mod(inv_factorial[i - 1], inv[i]);
        }
    }

    static int choose(int n, int r) {
        if (n < r || r < 0) return 0;
        return prod_mod(prod_mod(factorial[n], inv_factorial[r]), inv_factorial[n - r]);
    }

    static int arrangements(int n, int r) {
        return choose(n + r - 1, r - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        total_n = sc.nextInt();
        total_m = sc.nextInt();
        modulus = sc.nextInt();

        precompute(500);

        for (int i = 1; i <= total_n; i++) {
            prefix_sum[i] = sum_mod(prefix_sum[i - 1], i);
        }

        f_arr[0] = 1;
        f_arr[1] = 2;
        g_arr[0] = 0;
        g_arr[1] = 0;

        for (int i = 2; i <= total_n; i++) {
            for (int j = 0; j < i; j++) {
                int temp_val = prod_mod(choose(i - 1, j), prod_mod(f_arr[j], f_arr[i - 1 - j]));
                f_arr[i] = sum_mod(f_arr[i], prod_mod(temp_val, i + 1));
                g_arr[i] = sum_mod(g_arr[i], prod_mod(temp_val, prefix_sum[j] + prefix_sum[i - 1 - j]));
                int temp2 = prod_mod(
                        add_mod(prod_mod(g_arr[j], f_arr[i - 1 - j]), prod_mod(g_arr[i - 1 - j], f_arr[j])),
                        i + 1);
                g_arr[i] = sum_mod(g_arr[i], prod_mod(temp2, choose(i - 1, j)));
            }
        }

        f_table[0][0] = 1;
        g_table[0][0] = 0;

        for (int i = 0; i <= total_m; i++) {
            for (int j = 0; j <= total_m; j++) {
                if (f_table[i][j] == 0) continue;
                for (int k = 1; k + j <= total_m; k++) {
                    f_table[i + 1][j + k] = sum_mod(f_table[i + 1][j + k],
                            prod_mod(prod_mod(f_table[i][j], f_arr[k]), choose(j + k, k)));
                    g_table[i + 1][j + k] = sum_mod(g_table[i + 1][j + k],
                            prod_mod(add_mod(prod_mod(g_table[i][j], f_arr[k]), prod_mod(f_table[i][j], g_arr[k])), choose(j + k, k)));
                }
            }
        }

        int answer = 0;
        for (int i = 1; i <= total_m; i++) {
            if (total_n + 1 - total_m >= i) {
                answer = sum_mod(answer, prod_mod(g_table[i][total_m], arrangements(total_n + 1 - total_m - i, i + 1)));
            }
        }

        System.out.println(answer);
        sc.close();
    }

    static int add_mod(int a, int b) {
        return (a + b) % modulus;
    }
